// Des: Command dispatch: status, fetch, run, export, canary, kill
// Flo: parse args > build context > route by command word > each command prints text or --json > returns exit code
// I/O: process Init (main) > exit code 0-4; stdout results
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const targ = @import("ct-ctrl-args.zig"); const runz = @import("ct-ctrl-runz.zig"); const clou = @import("ct-ctrl-clou.zig"); const exit = @import("ct-exit-code.zig"); const cfgz = @import("cf-conf-load.zig"); const urln = @import("ut-urlz-norm.zig"); const ladd = @import("ru-tier-ladd.zig"); const fron = @import("qu-fron-main.zig"); const kill = @import("ru-kill-swit.zig"); const spen = @import("ru-spen-guar.zig"); const base = @import("nt-vend-base.zig"); const pipe = @import("ru-page-fetc.zig"); const brwx = @import("ct-ctrl-brow.zig"); const strx = @import("ct-ctrl-strm.zig"); const repl = @import("ct-spec-repl.zig"); const benc = @import("ct-ctrl-benc.zig"); const sitx = @import("ct-ctrl-site.zig");
const CF = .{ .vers = "0.1.0", .help = "scra " ++ "0.1.0 - cheapest good page, free first\n  status [--json]                      read-only\n  fetch <url> [--live [--force]]       dry-run unless --live; --force allows paid spend\n  run [url] [--seed-file f] [--sitemap u] [--decl n] [--live [--force]]\n  export [--format jsonl|csv] [--out file]\n  canary [--add url] [--live]\n  kill [--on|--off]                    stop or allow all vendor spend\n  sync [--live]                        upload to the cloud (local first), purge at 90%\n  login <name>                         owner logs in by hand in own Chrome profile (logi_mode_enab + brow_enab)\n  fetch options: --geoz cc --wait ms --selector css --scroll n --click text --consent --steps f.json --account name --stream sse|poll|ws\n  replay --spec f --param k=v [--live]   replay your own HAR or curl capture\n  bench --list f [--out file] [--live]  L1-L9 URL list, hit rate and cost per good page\n  run option: --follow n               follow n safe links (hidden and nofollow links are skipped)\nexit: 0 ok, 1 fail, 2 usage, 3 drift, 4 blocked" };
const Vstz = struct { vend: []const u8, used: i64, free: u32, okay: i64, tota: i64 };
const Stat = struct { appz: []const u8, vers: []const u8, mode: []const u8, kill: bool, capz_micr: u64, spen_micr: i64, disk_gbyt: u32, clou_mode: []const u8, logi_enab: bool, data_path: []const u8, vend_orde: []const []const u8, ven2: []const Vstz, pend: i64, done: i64, dead: i64, pags: i64 };
const Dryf = struct { mode: []const u8, urlz: []const u8, tie3: []const u8, wors_cred: u32, wors_micr: u64, note: []const u8 };
fn con2(dbzz: *@import("st-stor-sqli.zig").Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
fn vsta(ctx2: *const ctx3.Ctxz, dbzz: *@import("st-stor-sqli.zig").Dbzz, nowz: i64) ![]const Vstz { var list: std.ArrayList(Vstz) = .empty; for (ctx2.conf.vend_orde) |name| { const vend = base.vendFind(name) orelse continue; var stmt = try dbzz.prep("SELECT coalesce(sum(code>=200 AND code<300),0),count(*) FROM logz WHERE vend=?1;"); defer stmt.fini(); try stmt.bindText(1, name); _ = try stmt.step(); try list.append(ctx2.allo, .{ .vend = name, .used = try spen.spenUsed(dbzz, vend, nowz), .free = spen.freeOfzz(ctx2.conf, vend), .okay = stmt.colzIntz(0), .tota = stmt.colzIntz(1) }); } return list.toOwnedSlice(ctx2.allo); }
fn runzStat(ctx2: *const ctx3.Ctxz) !u8 { const conf = ctx2.conf; var stat: Stat = .{ .appz = "scra", .vers = CF.vers, .mode = "read-only", .kill = false, .capz_micr = cfgz.capzMicr(conf), .spen_micr = 0, .disk_gbyt = conf.capz_disk_gbyt, .clou_mode = conf.clou_poli_mode, .logi_enab = conf.logi_mode_enab, .data_path = cfgz.dataDirz(conf), .vend_orde = conf.vend_orde, .ven2 = &.{}, .pend = 0, .done = 0, .dead = 0, .pags = 0 };
if (ctx3.dbzzHave(ctx2)) { var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const nowz = pipe.nowzMill(ctx2.iozz); stat.kill = try kill.killGetz(&dbzz); stat.spen_micr = try spen.spenTota(&dbzz, nowz); stat.ven2 = try vsta(ctx2, &dbzz, nowz); stat.pend = try fron.fronCont(&dbzz, 0); stat.done = try fron.fronCont(&dbzz, 1); stat.dead = try fron.fronCont(&dbzz, 2); stat.pags = try con2(&dbzz, "SELECT count(*) FROM page;"); }
const plai = try std.fmt.allocPrint(ctx2.allo, "scra {s} | {s} | kill {} | spend {d}/{d} micro-USD | pages {d} | queue {d} pending {d} dead | disk cap {d} GB", .{ stat.vers, stat.mode, stat.kill, stat.spen_micr, stat.capz_micr, stat.pags, stat.pend, stat.dead, stat.disk_gbyt }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, stat, plai)); return 0; }
fn runzFetc(ctx2: *const ctx3.Ctxz) !u8 { if (ctx2.args.urlz.len == 0) return error.BadUsage; const norm = urln.urlzNorm(ctx2.allo, ctx2.args.urlz) catch return error.BadUsage;
if (!ctx2.args.live) { const estz = runz.estzWors(ctx2.conf, ctx2.args.geoz); const dryz: Dryf = .{ .mode = "dry-run", .urlz = norm, .tie3 = "T1 own GET (free) > T2 vendor plain > T3 render > T4 premium", .wors_cred = estz.cred, .wors_micr = estz.micr, .note = "vendors only if own GET is blocked; paid only with --live --force; nothing written" }; try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, dryz, try std.fmt.allocPrint(ctx2.allo, "dry-run | {s} | T1 own GET free | worst case {d} vendor credits ({d} micro-USD) | add --live to run", .{ norm, estz.cred, estz.micr }))); return 0; }
if (ctx2.args.strm.len > 0) return strx.runzStrm(ctx2); var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); var real = try ctx3.realMake(ctx2); var brwz = try brwx.brwzMake(ctx2, ctx2.args.acct); defer if (brwz) |*bwzz| bwzz.deinit(); var ladz: ladd.Ladd = .{ .gpaz = ctx2.init.gpa, .iozz = ctx2.iozz, .conf = ctx2.conf, .dbzz = &dbzz, .dirz = ctx2.dirz, .back = real.bac2(), .gozz = ctx2.args.forc, .geoz = ctx2.args.geoz, .wait = ctx2.args.wait, .sele = ctx2.args.sele, .acts = try brwx.actsOfzz(ctx2), .acct = ctx2.args.acct, .sess = if (brwz) |*bwzz| bwzz else null }; const outc = try ladd.laddFetc(&ladz, ctx2.allo, ctx2.args.urlz); const plai = try std.fmt.allocPrint(ctx2.allo, "{s} | {d} | T{d} {s} | {s} | {s}", .{ outc.stat, outc.code, outc.tier, outc.vend, outc.urlz, outc.hexz }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outc, plai)); return exit.outcCode(outc.stat, outc.code); }
fn runzKill(ctx2: *const ctx3.Ctxz) !u8 { var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); if (ctx2.args.onzz) try kill.killSetz(&dbzz, true); if (ctx2.args.offz) try kill.killSetz(&dbzz, false); const onzz = try kill.killGetz(&dbzz); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "kill switch {s}", .{if (onzz) "ON: all vendor spend halted" else "off"})); return 0; }
pub fn runzMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.argsRead(argv.items, allo); if (args.helz or std.mem.eql(u8, args.cmdz, "help") or args.cmdz.len == 0) { try std.Io.File.stdout().writeStreamingAll(init.io, CF.help ++ "\n"); return if (args.cmdz.len == 0 and !args.helz) 2 else 0; } const ctx2 = try ctx3.ctxzMake(init, args);
if (std.mem.eql(u8, args.cmdz, "status")) return runzStat(&ctx2); if (std.mem.eql(u8, args.cmdz, "fetch")) return runzFetc(&ctx2); if (std.mem.eql(u8, args.cmdz, "run")) return runz.runzRunz(&ctx2); if (std.mem.eql(u8, args.cmdz, "export")) return runz.runzExpo(&ctx2); if (std.mem.eql(u8, args.cmdz, "canary")) return runz.runzCana(&ctx2); if (std.mem.eql(u8, args.cmdz, "kill")) return runzKill(&ctx2); if (std.mem.eql(u8, args.cmdz, "sync")) return clou.runzSync(&ctx2); if (std.mem.eql(u8, args.cmdz, "login")) return brwx.runzLogi(&ctx2); if (std.mem.eql(u8, args.cmdz, "replay")) return repl.runzRepl(&ctx2); if (std.mem.eql(u8, args.cmdz, "bench")) return benc.runzBenc(&ctx2); if (std.mem.eql(u8, args.cmdz, "site")) return sitx.siteShow(&ctx2); return error.BadUsage; }
